def escape_html(text: str) -> str:
    """HTML 文本转义。``&`` 必须最先转义，否则实体本身会被二次转义。"""
    return (
        text.replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace('"', "&quot;")
    )

